#include <vector>
#include <iostream>

int main() {
    std::vector<int> coll;

    // DANGER: UB due to empty container access
    // std::cout << coll.front(); 
    // coll[0] = 5; 

    // Correct usage: Check size before access
    if (!coll.empty()) {
        std::cout << coll.front(); // Safe if size > 0
    } else {
        std::cout << "Container is empty.\n";
    }

    coll.push_back(10);
    std::cout << "Front (Safe): " << coll.front() << std::endl;
}
